  qUESTION("QUESTION"),
  mCPELICITATION("MCP_ELICITATION"),
  eXITPLAN("EXIT_PLAN");

  const InteractionKindV1(this.wire);

  final String wire;

  static InteractionKindV1 fromWire(String value) {
    for (final item in values) {
      if (item.wire == value) return item;
    }
    throw FormatException('Unknown InteractionKindV1 value: $value');
  }
}

final class InteractionRefV1 {
  const InteractionRefV1({
    required this.sourcePartition,
    required this.threadRef,
    required this.turnRef,
    required this.interactionId,
    required this.interactionKind,
  });

  final SourcePartitionV1 sourcePartition;
  final ThreadRefV1 threadRef;
  final TurnRefV1 turnRef;
  final String interactionId;
  final InteractionKindV1 interactionKind;

  factory InteractionRefV1.fromJson(Map<String, Object?> json) {
    _expectKeys(
      json,
      const {
        "sourcePartition",
        "threadRef",
        "turnRef",
        "interactionId",
        "interactionKind",
      },
