sealed class InteractionResolutionV1 {
  const InteractionResolutionV1();

  factory InteractionResolutionV1.fromJson(Map<String, Object?> json) {
    final tag = _expectString(json["kind"], "InteractionResolutionV1.kind");
    return switch (tag) {
      "approval" => InteractionResolutionV1Approval.fromJson(json),
      "question" => InteractionResolutionV1Question.fromJson(json),
      "mcp_elicitation" => InteractionResolutionV1McpElicitation.fromJson(json),
      "exit_plan" => InteractionResolutionV1ExitPlan.fromJson(json),
      _ => throw FormatException(
        'Unknown InteractionResolutionV1 discriminator: $tag',
      ),
    };
  }

  Map<String, Object?> toJson();
}

