final class InteractionSnapshotV1 {
  const InteractionSnapshotV1({
    required this.sourceEpoch,
    required this.descriptor,
    required this.state,
    required this.revision,
    this.claim,
    this.resolution,
  });

  final SourceEpochV1 sourceEpoch;
  final InteractionDescriptorV1 descriptor;
  final InteractionSnapshotV1State state;
  final AggregateRevisionV1 revision;
  final ClaimLeaseSnapshotV1? claim;
  final InteractionResolutionV1? resolution;

  factory InteractionSnapshotV1.fromJson(Map<String, Object?> json) {
    _expectKeys(
      json,
      const {"sourceEpoch", "descriptor", "state", "revision"},
      const {
        "sourceEpoch",
        "descriptor",
        "state",
        "revision",
        "claim",
        "resolution",
      },
      "InteractionSnapshotV1",
    );
    return InteractionSnapshotV1(
      sourceEpoch: SourceEpochV1.fromJson(
        _expectMap(json["sourceEpoch"], "InteractionSnapshotV1.sourceEpoch"),
      ),
      descriptor: InteractionDescriptorV1.fromJson(
        _expectMap(json["descriptor"], "InteractionSnapshotV1.descriptor"),
      ),
      state: InteractionSnapshotV1State.fromWire(
        _expectString(json["state"], "InteractionSnapshotV1.state"),
      ),
      revision: _expectInt(json["revision"], "InteractionSnapshotV1.revision"),
      claim: json.containsKey("claim")
          ? ClaimLeaseSnapshotV1.fromJson(
              _expectMap(json["claim"], "InteractionSnapshotV1.claim"),
            )
          : null,
      resolution: json.containsKey("resolution")
          ? InteractionResolutionV1.fromJson(
              _expectMap(
                json["resolution"],
                "InteractionSnapshotV1.resolution",
              ),
            )
          : null,
    );
  }

  Map<String, Object?> toJson() => {
    "sourceEpoch": sourceEpoch.toJson(),
    "descriptor": descriptor.toJson(),
    "state": state.wire,
    "revision": revision,
    if (claim != null) "claim": claim!.toJson(),
    if (resolution != null) "resolution": resolution!.toJson(),
  };
}

