  wIRESHAPEINVALID("WIRE_SHAPE_INVALID"),
  sOURCEFENCEMISMATCH("SOURCE_FENCE_MISMATCH"),
  sTALEGENERATION("STALE_GENERATION"),
  tIMELINEEMPTYPROOFINVALID("TIMELINE_EMPTY_PROOF_INVALID"),
  tIMELINEORDERGAPINVALID("TIMELINE_ORDER_GAP_INVALID"),
  tIMELINELASTGOODREGRESSION("TIMELINE_LAST_GOOD_REGRESSION"),
  tIMELINELIVEPROMOTIONINVALID("TIMELINE_LIVE_PROMOTION_INVALID"),
  cACHEREUSEVIOLATION("CACHE_REUSE_VIOLATION"),
  oPERATIONVARIANTINVALID("OPERATION_VARIANT_INVALID"),
  oPERATIONFINGERPRINTCONFLICT("OPERATION_FINGERPRINT_CONFLICT"),
  dURABLEADMISSIONREQUIRED("DURABLE_ADMISSION_REQUIRED"),
  oUTCOMEUNKNOWN("OUTCOME_UNKNOWN"),
  qUEUEREVISIONCONFLICT("QUEUE_REVISION_CONFLICT"),
  iNTERACTIONWRONGSOURCE("INTERACTION_WRONG_SOURCE"),
  iNTERACTIONWRONGACTOR("INTERACTION_WRONG_ACTOR"),
  iNTERACTIONEXPIRED("INTERACTION_EXPIRED"),
  iNTERACTIONDUPLICATERESPONSE("INTERACTION_DUPLICATE_RESPONSE"),
  wRONGINTERACTIONVARIANT("WRONG_INTERACTION_VARIANT"),
  cLAUDENOTIMPLEMENTED("CLAUDE_NOT_IMPLEMENTED"),
  cAPABILITYUNAVAILABLE("CAPABILITY_UNAVAILABLE"),
  pROVIDERMETHODNOTSUPPORTED("PROVIDER_METHOD_NOT_SUPPORTED"),
  tURNPAYLOADOVERSIZED("TURN_PAYLOAD_OVERSIZED"),
  tIMELINEPAGEBODYTOOLARGE("TIMELINE_PAGE_BODY_TOO_LARGE"),
  iMAGEMETADATACONFLICT("IMAGE_METADATA_CONFLICT"),
  iMAGESIZEEXCEEDED("IMAGE_SIZE_EXCEEDED"),
  iMAGEDIGESTMISMATCH("IMAGE_DIGEST_MISMATCH"),
  iMAGEMIMEUNSUPPORTED("IMAGE_MIME_UNSUPPORTED"),
  tURNIMAGECOUNTEXCEEDED("TURN_IMAGE_COUNT_EXCEEDED"),
  iMAGEINGRESSREJECTED("IMAGE_INGRESS_REJECTED"),
  jCSINVALID("JCS_INVALID"),
  oPERATIONFINGERPRINTINVALID("OPERATION_FINGERPRINT_INVALID"),
  mESSAGEIDENTITYINVALID("MESSAGE_IDENTITY_INVALID"),
  mATERIALIZATIONCOMMITINVALID("MATERIALIZATION_COMMIT_INVALID"),
  iNTEGRITYCONFLICT("INTEGRITY_CONFLICT"),
  mACHINETRANSITIONINVALID("MACHINE_TRANSITION_INVALID"),
  oPERATIONACTORMISMATCH("OPERATION_ACTOR_MISMATCH");

  const ProblemCodeV1(this.wire);

  final String wire;

  static ProblemCodeV1 fromWire(String value) {
    for (final item in values) {
