      "capability_snapshot" => ServerMessageV1CapabilitySnapshot.fromJson(json),
      "timeline_begin" => ServerMessageV1TimelineBegin.fromJson(json),
      "timeline_page" => ServerMessageV1TimelinePage.fromJson(json),
      "timeline_commit" => ServerMessageV1TimelineCommit.fromJson(json),
