sealed class TimelineStructuralGapTargetV1 {
  const TimelineStructuralGapTargetV1();

  factory TimelineStructuralGapTargetV1.fromJsonValue(Object? value) {
    TimelineStructuralGapTargetV1? matched;
    var matchCount = 0;
    try {
      final decoded = TimelineStructuralGapTargetV1Variant1Value.fromJson(
        _expectMap(value, "TimelineStructuralGapTargetV1<oneOf:1>"),
      );
      matched = TimelineStructuralGapTargetV1Variant1(decoded);
      matchCount += 1;
    } on FormatException {
      // A different closed branch may still match.
    }
    try {
      final decoded = TimelineStructuralGapTargetV1Variant2Value.fromJson(
        _expectMap(value, "TimelineStructuralGapTargetV1<oneOf:2>"),
      );
      matched = TimelineStructuralGapTargetV1Variant2(decoded);
      matchCount += 1;
    } on FormatException {
      // A different closed branch may still match.
    }
    try {
      final decoded = TimelineStructuralGapTargetV1Variant3Value.fromJson(
        _expectMap(value, "TimelineStructuralGapTargetV1<oneOf:3>"),
      );
      matched = TimelineStructuralGapTargetV1Variant3(decoded);
      matchCount += 1;
    } on FormatException {
      // A different closed branch may still match.
    }
    try {
      final decoded = TimelineStructuralGapTargetV1Variant4Value.fromJson(
        _expectMap(value, "TimelineStructuralGapTargetV1<oneOf:4>"),
      );
      matched = TimelineStructuralGapTargetV1Variant4(decoded);
      matchCount += 1;
    } on FormatException {
      // A different closed branch may still match.
    }
    if (matchCount == 0)
      throw const FormatException(
        'TimelineStructuralGapTargetV1: NO_ONE_OF_VARIANT',
      );
    if (matchCount > 1)
      throw const FormatException(
        'TimelineStructuralGapTargetV1: AMBIGUOUS_ONE_OF_VARIANT',
      );
    return matched!;
  }

  Object? toJson();
}

