sealed class TransactionSegmentV1 {
  const TransactionSegmentV1();

  factory TransactionSegmentV1.fromJsonValue(Object? value) {
    TransactionSegmentV1? matched;
    var matchCount = 0;
    try {
      final decoded = SqlTransactionSegmentV1.fromJson(
        _expectMap(value, "TransactionSegmentV1<oneOf:1>"),
      );
      matched = TransactionSegmentV1Variant1(decoded);
      matchCount += 1;
    } on FormatException {
      // A different closed branch may still match.
    }
    try {
      final decoded = ExternalEffectSegmentV1.fromJson(
        _expectMap(value, "TransactionSegmentV1<oneOf:2>"),
      );
      matched = TransactionSegmentV1Variant2(decoded);
      matchCount += 1;
    } on FormatException {
      // A different closed branch may still match.
    }
    if (matchCount == 0)
      throw const FormatException('TransactionSegmentV1: NO_ONE_OF_VARIANT');
    if (matchCount > 1)
      throw const FormatException(
        'TransactionSegmentV1: AMBIGUOUS_ONE_OF_VARIANT',
      );
    return matched!;
  }

  Object? toJson();
}

