        'pvmc1MachineEdgeAuthorities',
        (value) => _pvmc1ImmutableMachineEdgeAuthority(
          MachineEdgeAuthorityV1.fromJson(
            _expectMap(value, 'pvmc1MachineEdgeAuthorities[]'),
          ),
        ),
        minItems: 151,
        maxItems: 151,
      ),
    );

const List<String> pvmc1DurableRouteIds = [
  "sync.gap.v1",
  "materialization.begin.v1:TIMELINE",
  "materialization.page.v1:TIMELINE",
  "materialization.commit.v1:TIMELINE",
  "operation.state.v1",
  "queue.snapshot.v1",
  "interaction.snapshot.v1",
];

String _pvmc1MachineEdgeKey(MachineEdgeAuthorityV1 row) {
  final coordinate = row.coordinate.toJson();
  return _expectString(coordinate['machineId'], 'pvmc1MachineEdge.machineId') +
      '\u0000' +
      _expectString(coordinate['from'], 'pvmc1MachineEdge.from') +
      '\u0000' +
      _expectString(coordinate['to'], 'pvmc1MachineEdge.to');
}

final Set<String> _pvmc1AllowedMachineEdgeKeys = Set<String>.unmodifiable(
  pvmc1MachineEdgeAuthorities.map(_pvmc1MachineEdgeKey),
);

bool isAllowedPvmc1MachineEdge(String machineId, String from, String to) =>
    _pvmc1AllowedMachineEdgeKeys.contains('$machineId\u0000$from\u0000$to');

const int pvmc1MachineTransitionSqlRowCount = 151;
const String pvmc1MachineTransitionSqlSha256 =
    "4caa5d71547050f8f7fc32448b32cc088ed59f165ced3bdce776bf63817c237c";
const String pvmc1MachineTransitionSqlUtf8Base64 =
    "";

Uint8List pvmc1MachineTransitionSqlBytes() {
  final bytes = Uint8List.fromList(
    base64Decode(pvmc1MachineTransitionSqlUtf8Base64),
  );
  if (sha256.convert(bytes).toString() != pvmc1MachineTransitionSqlSha256) {
    throw StateError('PVMC1 machine SQL digest mismatch');
  }
  return bytes;
}

